package org.ikigaidigital.adapter.in.web;

import org.ikigaidigital.adapter.in.web.api.model.TimeDepositDto;
import org.ikigaidigital.adapter.in.web.api.model.WithdrawalDto;
import org.ikigaidigital.application.TimeDepositWithWithdrawals;
import org.ikigaidigital.domain.Money;
import org.ikigaidigital.domain.Withdrawal;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingConstants;

import java.util.List;

/**
 * Maps the application read model to the DTOs generated from the OpenAPI contract (generated by MapStruct).
 * {@link Money#toCents(Double)} turns the legacy double balance into a decimal with cents.
 */
@Mapper(componentModel = MappingConstants.ComponentModel.SPRING, uses = Money.class)
interface TimeDepositDtoMapper {

    List<TimeDepositDto> toDtos(List<TimeDepositWithWithdrawals> source);

    @Mapping(target = "id", source = "timeDeposit.id")
    @Mapping(target = "planType", source = "timeDeposit.planType")
    @Mapping(target = "balance", source = "timeDeposit.balance")
    @Mapping(target = "days", source = "timeDeposit.days")
    TimeDepositDto toDto(TimeDepositWithWithdrawals source);

    // Withdrawal.timeDepositId is not part of the API: withdrawals are nested under their deposit.
    WithdrawalDto toDto(Withdrawal withdrawal);
}
